const body = $input.first().json.body;
const userId = body.user_id;
const sessionId = body.session_id;

if (!userId && !sessionId) {
  return {
    json: {
      success: false,
      error: 'user_id or session_id required'
    }
  };
}

const supabaseUrl = 'https://ybpsseqzzhttnbpiqaws.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InlicHNzZXF6emh0dG5icGlxYXdzIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NzQ3NjUzMywiZXhwIjoyMDgzMDUyNTMzfQ.mqVQjdOswUYHV0b0CNZcd2TZSaIxYkIIrUjZjVv9hTc';

try {
  // Build query filter
  let filter = '';
  if (userId) {
    filter = `user_id=eq.${userId}`;
  } else if (sessionId) {
    filter = `session_id=eq.${sessionId}`;
  }

  // Fetch conversations
  const conversations = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/conversations?${filter}&order=started_at.desc`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`
    },
    json: true
  });

  // For each conversation, get message count and preview
  const conversationsWithDetails = await Promise.all(
    conversations.map(async (conv) => {
      try {
        // Get first message and all messages in parallel
        const [firstMessage, allMessages] = await Promise.all([
          this.helpers.httpRequest({
            method: 'GET',
            url: `${supabaseUrl}/rest/v1/messages?conversation_id=eq.${conv.id}&order=sequence_number.asc&limit=1&select=content`,
            headers: {
              'apikey': supabaseKey,
              'Authorization': `Bearer ${supabaseKey}`
            },
            json: true
          }),
          this.helpers.httpRequest({
            method: 'GET',
            url: `${supabaseUrl}/rest/v1/messages?conversation_id=eq.${conv.id}&select=id`,
            headers: {
              'apikey': supabaseKey,
              'Authorization': `Bearer ${supabaseKey}`
            },
            json: true
          })
        ]);

        const messageCount = Array.isArray(allMessages) ? allMessages.length : 0;
        const preview = Array.isArray(firstMessage) && firstMessage.length > 0 
          ? firstMessage[0].content.substring(0, 60) + (firstMessage[0].content.length > 60 ? '...' : '')
          : 'New conversation';

        return {
          id: conv.id,
          started_at: conv.started_at,
          ended_at: conv.ended_at || null,
          message_count: messageCount,
          preview: preview
        };
      } catch (err) {
        // If error getting messages, return basic info
        return {
          id: conv.id,
          started_at: conv.started_at,
          ended_at: conv.ended_at || null,
          message_count: 0,
          preview: 'New conversation'
        };
      }
    })
  );

  return {
    json: {
      success: true,
      conversations: conversationsWithDetails
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message || 'Failed to fetch conversations',
      conversations: []
    }
  };
}
